function Foo({ _Bar }: { _Bar: React.ComponentType }) {
    return (
      <_Bar>
        {() => <div />}
      </_Bar>
    );
  }
is compiled to the following:
import { c as _c } from "react/compiler-runtime";
function Foo(t0) {
  const $ = _c(1);
  let t1;
  if ($[0] === Symbol.for("react.memo_cache_sentinel")) {
    t1 = <_Bar>{_temp}</_Bar>;
